const { Browser } = require('happy-dom');
const fs = require('fs');

const browser = new Browser();
const page = browser.newPage();

// Load app (same approach as world.js)
const html = fs.readFileSync('index.html', 'utf8');
const appJs = fs.readFileSync('js/app.js', 'utf8');

const bodyMatch = html.match(/<body[^>]*>([\s\S]*)<\/body>/i);
const bodyContent = bodyMatch ? bodyMatch[1] : '';
const cleanedBody = bodyContent.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');

page.evaluate(
  `document.documentElement.innerHTML = '<head></head><body>' +
    cleanedBody.replace(/'/g, "\\'").replace(/\n/g, '\\n').replace(/\r/g, '\\r') +
    '</body>';`
);
page.waitUntilComplete();

// Hmm, escaping issues. Let's use Function constructor approach
page.evaluate(`document.documentElement.innerHTML = '<head></head><body></body>'`);
page.waitUntilComplete();

page.evaluate(`document.body.innerHTML = \`${cleanedBody.replace(/`/g, '\\`').replace(/\$/g, '\\$')}\`;`);
page.waitUntilComplete();
page.evaluate(appJs);
page.waitUntilComplete();

// Create a todo
page.evaluate(function() {
  var input = document.querySelector('.new-todo');
  input.value = 'Buy groceries';
  input.dispatchEvent(new KeyboardEvent('keypress', {key:'Enter', keyCode:13, bubbles:true}));
});
page.waitUntilComplete();

// Capture the row element reference, toggle it, then check same element got completed class
var result = page.evaluate(function() {
  var li = document.querySelector('.todo-list li');
  var ref = li;

  // Toggle via click
  var cb = li.querySelector('.toggle');
  cb.click();

  // After render: check if the SAME element (by === identity) has the class
  return {
    sameElement: li === ref,
    hasCompleted: li.classList.contains('completed'),
    checked: li.querySelector('.toggle').checked,
    className: li.className
  };
});

console.log('Same element identity preserved:', result.sameElement);
console.log('Has completed class:', result.hasCompleted);
console.log('Checkbox checked:', result.checked);
console.log('li.className:', result.className);
console.log('Overall:', result.sameElement && result.hasCompleted && result.checked ? 'PASS' : 'FAIL');

browser.close();

const { Browser } = require('happy-dom');
const fs = require('fs');

const browser = new Browser();
const page = browser.newPage();

function escapeJs(str) {
  return str
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r');
}

const indexPath = 'index.html';
const appJsPath = 'js/app.js';
const html = fs.readFileSync(indexPath, 'utf8');
const appJs = fs.readFileSync(appJsPath, 'utf8');

const bodyMatch = html.match(/<body[^>]*>([\s\S]*)<\/body>/i);
const bodyContent = bodyMatch ? bodyMatch[1] : '';
const cleanedBody = bodyContent.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');

page.evaluate(
  `document.documentElement.innerHTML = '<head></head><body>${escapeJs(cleanedBody)}</body>';`
);
page.waitUntilComplete();
page.evaluate(appJs);
page.waitUntilComplete();

// Create a todo
page.evaluate(function() {
  var input = document.querySelector('.new-todo');
  input.value = 'Buy groceries';
  input.dispatchEvent(new KeyboardEvent('keypress', {key:'Enter', keyCode:13, bubbles:true}));
});
page.waitUntilComplete();

// Capture the row element reference, toggle it, then check SAME element updated in place
var result = page.evaluate(function() {
  var li = document.querySelector('.todo-list li');
  var ref = li;  // hold a reference

  // Toggle via click on the checkbox
  var cb = li.querySelector('.toggle');
  cb.click();

  // After render: check if the SAME element (by === identity) has the class + checked state
  return {
    sameElement: li === ref,
    hasCompleted: li.classList.contains('completed'),
    checked: li.querySelector('.toggle').checked,
    className: li.className
  };
});

console.log('=== Element identity stability test ===');
console.log('Same element identity preserved:', result.sameElement);
console.log('Has completed class:', result.hasCompleted);
console.log('Checkbox checked:', result.checked);
console.log('li.className:', JSON.stringify(result.className));
console.log('RESULT:', result.sameElement && result.hasCompleted && result.checked ? 'PASS' : 'FAIL');

// Now test unmark (toggle back)
var result2 = page.evaluate(function() {
  var li = document.querySelector('.todo-list li');
  var ref = li;

  var cb = li.querySelector('.toggle');
  cb.click();

  return {
    sameElement: li === ref,
    hasCompleted: li.classList.contains('completed'),
    checked: li.querySelector('.toggle').checked,
    className: li.className
  };
});

console.log('\n=== Unmark (toggle back) ===');
console.log('Same element identity preserved:', result2.sameElement);
console.log('Has completed class:', result2.hasCompleted);
console.log('Checkbox checked:', result2.checked);
console.log('li.className:', JSON.stringify(result2.className));
console.log('RESULT:', result2.sameElement && !result2.hasCompleted && !result2.checked ? 'PASS' : 'FAIL');

// Mark-all test
page.evaluate(function() {
  var input = document.querySelector('.new-todo');
  input.value = 'Walk dog';
  input.dispatchEvent(new KeyboardEvent('keypress', {key:'Enter', keyCode:13, bubbles:true}));
  input.value = 'Write code';
  input.dispatchEvent(new KeyboardEvent('keypress', {key:'Enter', keyCode:13, bubbles:true}));
});
page.waitUntilComplete();

var result3 = page.evaluate(function() {
  var items = Array.from(document.querySelectorAll('.todo-list li'));
  var refs = items.slice(); // hold references

  // Click toggle-all
  document.querySelector('#toggle-all').click();

  // Check every held reference is the same element and has completed class
  var allSame = items.every(function(li, i) { return li === refs[i]; });
  var allCompleted = items.every(function(li) { return li.classList.contains('completed'); });
  return {
    allSame: allSame,
    allCompleted: allCompleted,
    allChecked: items.every(function(li) { return li.querySelector('.toggle').checked; })
  };
});

console.log('\n=== Toggle-all marks all ===');
console.log('All elements identity preserved:', result3.allSame);
console.log('All have completed class:', result3.allCompleted);
console.log('All checkboxes checked:', result3.allChecked);
console.log('RESULT:', result3.allSame && result3.allCompleted && result3.allChecked ? 'PASS' : 'FAIL');

// Toggle-all again to clear
var result4 = page.evaluate(function() {
  var items = Array.from(document.querySelectorAll('.todo-list li'));
  var refs = items.slice();

  document.querySelector('#toggle-all').click();

  var allSame = items.every(function(li, i) { return li === refs[i]; });
  var noneCompleted = items.every(function(li) { return !li.classList.contains('completed'); });
  return {
    allSame: allSame,
    noneCompleted: noneCompleted,
    noneChecked: items.every(function(li) { return !li.querySelector('.toggle').checked; })
  };
});

console.log('\n=== Toggle-all clears all ===');
console.log('All elements identity preserved:', result4.allSame);
console.log('None have completed class:', result4.noneCompleted);
console.log('No checkboxes checked:', result4.noneChecked);
console.log('RESULT:', result4.allSame && result4.noneCompleted && result4.noneChecked ? 'PASS' : 'FAIL');

browser.close();
